<?php

namespace Agent\AgentBundle\Repository;

/**
 * MutationRepository
 *
 * This class was generated by the Doctrine ORM. Add your own custom
 * repository methods below.
 */
class MutationRepository extends \Doctrine\ORM\EntityRepository {

    public function findMutationReceiveSRHMG($todo = null) {
        $qb = $this->createQueryBuilder('m')
                ->join('m.emmeteur', 'e')
                ->addSelect('e');
        //en attente de validation, autres services
        if ($todo == 0) {
            $qb->Where("m.etatRepDest = 1 and m.etatRepGrh = 0");
            //////archive autres services
        } elseif ($todo == 1) {
            $qb->Where("m.etatRepGrh > 0");
        }//////imprimer et numeriser
        elseif ($todo == 2) {
            $qb->Where("m.etatRepGrh > 0 and m.signeNote = 0");
        }
        $qb->orderBy('m.dateCreation', 'DESC');
        return $qb->getQuery()->getResult();
    }

    public function findMutationReceive($user, $todo = null) {
        //dump($user); die;
        /* $Direction = $user->getAgent()->getDirection();
          $SousDirection = $user->getAgent()->getCodeSd();
          $Service = $user->getAgent()->getCodeSc();
          $Fonction = $user->getAgent()->getFonction()->getId(); */
        $qb = $this->createQueryBuilder('m')
                ->join('m.emmeteur', 'e')
                ->addSelect('e');
        //en attente
        if ($todo == 0) {
            $qb->where("m.SupDir = :Users and m.etatRepSupDir = 0")
                    ->orWhere("m.supDest = :Users and m.etatRepDest = 0");
        }
        //
        elseif ($todo == 1) {
            $qb->where("m.SupDir = :Users and m.etatRepSupDir > 0")
                    ->orWhere("m.supDest = :Users and m.etatRepDest > 0");
        }
        $qb->setParameter("Users", $user->getAgent())
                ->orderBy('m.dateCreation', 'DESC');
        // dump($qb->getQuery()->getResult());
        //die;
        return $qb->getQuery()->getResult();
        //Chef de Service
    }

