    public function mutationSend($agent) {
        $matricule = $agent->getMatricule();
        $Fonction = $agent->getFonction()->getId();
        //die();
        if ($Fonction == 10 or in_array('ROLE_RESPO_SRHMG', $agent->getUsers()->getRoles())) {

            $qb = $this->createQueryBuilder('m')
                    ->where('m.TypeMutation = 2')
                    ->orderBy('m.dateCreation', 'DESC');
        } else {
            $qb = $this->createQueryBuilder('m')
                    ->join('m.emmeteur', 'e')
                    ->addSelect('m')
                    ->where("e.matricule = :Matricule and m.TypeMutation != 2")
                    ->setParameter("Matricule", $matricule)
                    ->orderBy('m.dateCreation', 'DESC');
        }
        return $qb->getQuery()->getResult();
    }

}
